INSERT OR IGNORE INTO posts (id,slug,title,excerpt,content,category,image,status,created_at,updated_at,published_at,image_alt,seo_title,seo_description) VALUES ('initial-draft-0','odpadove-hospodarstvo-kde-zacat','Odpadové hospodárstvo vo firme: kde začať?','Dobré nastavenie začína poznaním vlastnej prevádzky. Päť krokov pre prvý prehľad.','Začnite pri svojej prevádzke
Spíšte si, pri ktorých činnostiach vzniká odpad. Zahrňte výrobu, údržbu, administratívu aj skladovanie. Tento prehľad je východiskom pre rozhovor s odborníkom.

Zozbierajte dostupné podklady
Pripravte existujúcu evidenciu, doklady o odovzdaní odpadov, zmluvy a interné postupy. Neúplné podklady sú tiež užitočné: ukážu, čo treba doplniť.

Pozrite sa na každodennú prax
Kde sa odpad zhromažďuje? Kto je zaň zodpovedný? Vedia pracovníci, kam ho odložiť? Praktické nastavenie musí fungovať aj počas bežného pracovného dňa.

Dohodnite zodpovednosti
Určite kontaktnú osobu a spôsob odovzdávania dokladov. Prehľadná spolupráca znižuje riziko, že sa dôležité údaje stratia.

Nechajte si posúdiť konkrétne povinnosti
Tie závisia od vašej činnosti a vznikajúcich odpadov. Na úvodnej konzultácii vám pomôžeme zorientovať sa a navrhneme ďalšie kroky.','Pre firmy','/images/meadow.webp','published',1791841369447,1791844356867,1791844356867,'','','');
INSERT OR IGNORE INTO posts (id,slug,title,excerpt,content,category,image,status,created_at,updated_at,published_at,image_alt,seo_title,seo_description) VALUES ('initial-draft-1','nebezpecny-odpad-v-prevadzke','Nebezpečný odpad sa netýka len veľkých fabrík','Oleje, farby či znečistené obaly sa objavujú aj v malých prevádzkach. Dôležité je vedieť ich rozpoznať.','Aj malá prevádzka potrebuje prehľad
S odpadmi, ktoré môžu mať nebezpečné vlastnosti, sa stretávame napríklad pri opravách, údržbe, lakovaní alebo práci s chemikáliami. Veľkosť firmy sama osebe neurčuje charakter odpadu.

Čo si pripraviť na konzultáciu
Užitočný je opis procesu, pri ktorom odpad vzniká, informácie o používaných látkach a dostupná dokumentácia. Pri neistote je potrebné odborné posúdenie – samotný názov výrobku nemusí stačiť.

Od identifikácie k systému
Po identifikácii nasleduje správne zaradenie, nastavenie označovania a zhromažďovania, evidencia a potrebná dokumentácia. Konkrétne podmienky treba posúdiť podľa odpadu a prevádzky.

Máte otázky?
Opíšte nám svoju činnosť. Pomôžeme vám určiť, ktoré oblasti potrebujú pozornosť a aký postup je vhodný.','Nebezpečné odpady','/images/valley.webp','published',1791841369447,1791844382617,1791844382617,'','','');
INSERT OR IGNORE INTO posts (id,slug,title,excerpt,content,category,image,status,created_at,updated_at,published_at,image_alt,seo_title,seo_description) VALUES ('initial-draft-2','ako-sa-pripravit-na-konzultaciu','Čo si pripraviť na prvú konzultáciu?','Nemusíte mať odpoveď na všetko. Stačí začať činnosťou firmy a otázkami, ktoré vás trápia.','Povedzte nám, čomu sa venujete
Základom je stručný opis vašej činnosti, počtu a typu prevádzok a odpadov, s ktorými sa stretávate. Ak niektoré údaje nepoznáte, pomôžeme vám ich doplniť.

Pripravte dokumenty, ktoré už máte
Vezmite so sebou dostupnú evidenciu, doklady od partnerov a dokumentáciu k prevádzke. Nemusíte ich vopred dokonale usporiadať.

Spíšte si otázky
Čo je pre vás nejasné? Ktorá administratíva vám zaberá najviac času? Riešite zmeny vo výrobe alebo novú prevádzku? Aj tieto súvislosti nám pomôžu navrhnúť užitočnú spoluprácu.

Čo bude nasledovať
Prejdeme si aktuálny stav a dohodneme ďalšie kroky. Úvodné stretnutie je bezplatné; rozsah ďalšej spolupráce a cenu si dohodneme individuálne.','Praktické tipy','/images/hills.webp','published',1791841369447,1791844364461,1791844364461,'','','');

